def reviewed_alpha(rid,photo):
 size=photo.size
 if rid=='hb-4723':
  f=np.asarray(photo.convert('RGB'));mask=(f.min(2)<175);mask[:136]=False;mask[183:]=False;return Image.fromarray(np.uint8(mask)*255).filter(ImageFilter.GaussianBlur(.25))
 if rid not in CONTOURS and rid!='hb-5152':return None
 out=Image.new('L',(size[0]*4,size[1]*4));d=ImageDraw.Draw(out)
 if rid=='hb-5152':d.ellipse((65*4,46*4,278*4,261*4),fill=255)
 else:
  for pts in CONTOURS[rid]:d.polygon([(x*4,y*4) for x,y in pts],fill=255)
 alpha=out.resize(size,Image.Resampling.LANCZOS)
 # The pale floor below these dark bronze bodies is visibly distinct from
 # their surface. Restrict the cleanup to reviewed edge windows, retaining
 # the bright cast-metal highlights on the upper handles.
 if rid in {'hb-4724','hb-4739'}:
  f=np.asarray(photo.convert('RGB'));a=np.array(alpha);yy,xx=np.indices(a.shape)
  if rid=='hb-4724':zone=(yy>=198)&(yy<=228)&(xx>=91)&(xx<=257);lo,hi=125,170
  else:zone=((yy>=195)&(yy<=233)&(xx>=280))|((xx<=30)&(yy>=117)&(yy<=178));lo,hi=155,205
  edge=np.clip((hi-f.min(2).astype(float))/(hi-lo),0,1)*255
  a[zone]=np.minimum(a[zone],edge[zone].astype('uint8'));alpha=Image.fromarray(a)
 return alpha
